1	// GameBullApi.cs
2	// The "front door" — clean named methods the game calls.
3	// Each method uses GameBullClient (the fetcher) and parses JSON with Newtonsoft.
4	// The game NEVER touches URLs or UnityWebRequest — it just calls these.
5	
6	using System.Threading.Tasks;
7	using Newtonsoft.Json;
8	using UnityEngine;
9	
10	namespace GameBull
11	{
12	    // ---------- Response shapes (what the server sends back) ----------
13	
14	    // ---- /context response (the one boot call) ----
15	
16	    public class GameContext
17	    {
18	        public User                 user;
19	        public Lives                lives;
20	        public int                  points;
21	        public Customization        customization;
22	        public string[]             enabledModes;
23	        public ActiveOpenTournament activeOpenTournament;   // null if none
24	        public Room                 room;                   // null unless joiner (URL had roomId)
25	    }
26	
27	    public class User
28	    {
29	        public string displayName;
30	        public string globalUserId;
31	    }
32	
33	    public class Lives
34	    {
35	        public int    count;
36	        public int    max;
37	        public string nextRefillAt;            // nullable ISO timestamp
38	        public int    refillIntervalSeconds;
39	    }
40	
41	    public class Customization
42	    {
43	        public Colors  colors;
44	        public string  logoUrl;
45	        public Asset[] assets;
46	    }
47	
48	    public class Colors
49	    {
50	        public string primary;
51	        public string secondary;
52	    }
53	
54	    public class Asset
55	    {
56	        public string key;
57	        public string url;
58	        public string mimeType;
59	        public int    bytes;
60	    }
61	
62	    public class ActiveOpenTournament
63	    {
64	        public string id;
65	        public string name;
66	        public string endsAt;
67	        public int    participantCount;
68	    }
69	
70	    public class RoomPlayer
71	    {
72	        public string playerId;
73	        public string nickname;
74	        public int    score;
75	        public string finishedAt;
76	    }
77	
78	    public class Room
79	    {
80	        public string       id;
81	        public string       name;
82	        public string       state;
83	        public string       expiresAt;
84	        public RoomPlayer[] players;     // players already in the room (objects, not strings)
85	    }
86	
87	    public class ScoreResult
88	    {
89	        public string scoreId;
90	        public int    value;       // solo + tournament responses use "value"
91	        public int    score;       // room responses use "score"
92	        public bool   recorded;
93	        public string submittedAt;
94	        public string finishedAt;  // room responses include finishedAt
95	
96	        // Whichever the endpoint populated (room sets score, solo/tournament set value)
97	        public int effectiveValue => value != 0 ? value : score;
98	    }
99	
100	    // POST /play/plays response (v3.1) — mint a play token before the round (spends 1 life).
101	    [System.Serializable] public class PlayResult {
102	        public string playToken;
103	        public string seed;
104	        public string mode;
105	        public string expiresAt;
106	    }
107	
108	    public class RoomLeaderboard
109	    {
110	        public LeaderboardItem[] items;
111	        public bool   hasFinalScores;
112	        public string state;
113	        public string expiresAt;
114	    }
115	
116	    public class LeaderboardItem
117	    {
118	        public string playerId;
119	        public string nickname;
120	        public int    score;
121	        public int    rank;
122	        public string finishedAt;   // null/empty if still playing
123	    }
124	
125	    // Returned by POST /play/rooms (host creates a room)
126	    public class CreateRoomResult
127	    {
128	        public string roomId;
129	        public string roomName;
130	        public string joinUrl;
131	        public string seed;
132	        public string hostPlayerId;
133	        public string hostNickname;
134	        public int    maxPlayers;
135	        public string expiresAt;
136	    }
137	
138	    // Returned by POST /play/rooms/:roomId/join (friend joins)
139	    public class JoinRoomResult
140	    {
141	        public string playerId;
142	        public string nickname;
143	        public string seed;
144	        public string expiresAt;
145	    }
146	
147	    // ---------- Open Tournament API response shapes (match Swagger schema) ----------
148	
149	    [System.Serializable] public class OpenTournament {
150	        public string id;
151	        public string tenantId;
152	        public string gameId;
153	        public string name;
154	        public string description;
155	        public string startsAt;
156	        public string endsAt;
157	        public int?   maxPlayers;
158	        public PrizeTier[] prizeTiers;
159	        public string status;
160	        public int?   participantCount;
161	        public string createdAt;
162	    }
163	    [System.Serializable] public class PrizeTier {
164	        public int?   rank;
165	        public string label;
166	        public string giftId;
167	    }
168	    [System.Serializable] public class OpenTournamentList {
169	        public OpenTournament[] items;
170	    }
171	    [System.Serializable] public class TournamentJoinResult {
172	        public string entryId;
173	        public string nickname;
174	        public string joinedAt;
175	    }
176	    [System.Serializable] public class TournamentSession {
177	        public string sessionToken;
178	        public string seed;
179	        public string mode;
180	        public string expiresAt;
181	    }
182	    [System.Serializable] public class TournamentScoreResult {
183	        public string entryId;
184	        public int    score;
185	        public bool   improved;
186	        public int    rank;
187	        public string finishedAt;
188	    }
189	    [System.Serializable] public class TournamentLeaderboard {
190	        public TournamentLeaderboardItem[] items;
191	        public string status;
192	        public int    participantCount;
193	        public string startsAt;
194	        public string endsAt;
195	    }
196	    [System.Serializable] public class TournamentLeaderboardItem {
197	        public string entryId;
198	        public string nickname;
199	        public int    score;
200	        public int    rank;
201	        public string finishedAt;
202	    }
203	
204	    // ---------- Global Tournament API response shapes (NEW /game/global-tournaments) ----------
205	
206	    [System.Serializable] public class GlobalTournament {
207	        public string id;
208	        public string gameId;
209	        public string name;
210	        public string description;
211	        public string startsAt;
212	        public string endsAt;
213	        public string prizeModel;                                              // e.g. "TENANT_GB_POINTS" | "GLORY_ONLY"
214	        public System.Collections.Generic.Dictionary<string,int> prizeConfig;  // e.g. {"1":100,"2":50,"3":29}; empty for GLORY_ONLY
215	        public string status;
216	        public string finalizedAt;
217	        public int    participantCount;
218	    }
219	    [System.Serializable] public class GlobalTournamentList {
220	        public GlobalTournament[] items;
221	    }
222	    // Leaderboard shape differs from the old one: (rank, alias, score, isMe) — no entryId/finishedAt.
223	    // rank/score are nullable: the server sends null for players who haven't scored yet.
224	    [System.Serializable] public class GlobalLeaderboardItem {
225	        public int?   rank;
226	        public string alias;
227	        public int?   score;
228	        public bool   isMe;
229	    }
230	    [System.Serializable] public class GlobalLeaderboard {
231	        public GlobalLeaderboardItem[] items;
232	    }
233	    // GET /game/global-tournaments/my-rank — caller's own standing. rank/score are null until the player scores.
234	    [System.Serializable] public class GlobalMyRank {
235	        public int?   rank;
236	        public string alias;
237	        public int?   score;
238	        public bool   isMe;
239	    }
240	
241	    // ---------- My history (/me/rooms) response shapes (match live schema) ----------
242	
243	    [System.Serializable] public class MyRoom {
244	        public string roomId;
245	        public string roomName;
246	        public string gameId;
247	        public string state;
248	        public string expiresAt;
249	        public string createdAt;
250	        public string hostNickname;
251	        public int    playerCount;
252	        public bool   isHost;
253	        public string myPlayerId;
254	        public int    myBestScore;
255	    }
256	    [System.Serializable] public class MyRoomsList {
257	        public MyRoom[] items;
258	        public string nextCursor;
259	    }
260	
261	    // ---------- The API methods ----------
262	
263	    public static class GameBullApi
264	    {
265	        // v3.1 two-tier play: the play token minted by MintPlay(), used to submit the solo score.
266	        public static string CurrentPlayToken;
267	        public static string CurrentSeed;
268	        // v3.1 global tournaments: token from StartGlobalTournamentSession — used for the tournament
269	        // score submit and the leaderboard/my-rank reads (NOT the boot token).
270	        public static string CurrentGlobalToken;
271	
272	        // GET the per-tenant context (colors / logo / assets).
273	        // Uses the gameId + tenantSlug + sessionToken that GameBullBoot read from the URL.
274	        public static async Task<GameContext> GetContext()
275	        {
276	            string url = GameBullEndpoints.GameContext(GameBullBoot.GameId, GameBullBoot.TenantSlug, GameBullBoot.RoomId);
277	            string json = await GameBullClient.GetJson(url, GameBullBoot.SessionToken);
278	            if (string.IsNullOrEmpty(json)) return null;
279	            var result = JsonConvert.DeserializeObject<GameContext>(json);
280	            Debug.Log($"[LIVES] GetContext url={url} → server lives.count={result?.lives?.count}");
281	            return result;
282	        }
283	
284	        // GET the public room leaderboard (no auth needed — leaderboard is public).
285	        public static async Task<RoomLeaderboard> GetRoomLeaderboard(string roomId)
286	        {
287	            string url  = $"{GameBullEndpoints.BaseUrl}/play/rooms/{roomId}/leaderboard";
288	            string json = await GameBullClient.GetJson(url, null);
289	            if (string.IsNullOrEmpty(json)) return null;
290	            return JsonConvert.DeserializeObject<RoomLeaderboard>(json);
291	        }
292	
293	        // POST a solo score (mode HEAD_TO_HEAD_1V1). Token goes in the BODY for GameBull.
294	        // v3.1: the token is the PLAY token (from MintPlay), NOT the boot token.
295	        public static async Task<ScoreResult> SubmitSoloScore(int score, int playTimeMs)
296	        {
297	            string url  = GameBullEndpoints.SoloScore();
298	            string body = JsonConvert.SerializeObject(new {
299	                sessionToken = CurrentPlayToken,   // v3.1: score with the PLAY token, not the boot token
300	                value        = score,
301	                playTimeMs   = playTimeMs
302	            });
303	            string json = await GameBullClient.PostJson(url, body);
304	            if (string.IsNullOrEmpty(json)) return null;
305	            return JsonConvert.DeserializeObject<ScoreResult>(json);
306	        }
307	
308	        // v3.1: mint a play token (POST /play/plays) BEFORE the round. Spends exactly 1 life.
309	        // Token goes in the BODY as bootToken (no Bearer), same style as SubmitSoloScore.
310	        // Returns null on any failure (incl. play.no_lives) — caller must NOT start the game.
311	        public static async Task<PlayResult> MintPlay()
312	        {
313	            string url  = GameBullEndpoints.Plays();
314	            string body = JsonConvert.SerializeObject(new { bootToken = GameBullBoot.SessionToken });
315	            string json = await GameBullClient.PostJson(url, body);   // 2-arg, no Bearer
316	            if (string.IsNullOrEmpty(json)) return null;
317	            try { return JsonConvert.DeserializeObject<PlayResult>(json); }
318	            catch (System.Exception e) { Debug.LogWarning("[GameBull] Play mint parse failed: " + e.Message + "\n" + json); return null; }
319	        }
320	
321	        // POST a 4-player room score (mode TOURNAMENT_ROOM). Uses playerId from the URL.
322	        public static async Task<ScoreResult> SubmitRoomScore(int score, int playTimeMs)
323	        {
324	            string url  = GameBullEndpoints.RoomScore(GameBullBoot.RoomId);
325	            string body = JsonConvert.SerializeObject(new {
326	                playerId   = GameBullBoot.PlayerId,
327	                score      = score,
328	                playTimeMs = playTimeMs
329	            });
330	            string json = await GameBullClient.PostJson(url, body);
331	            if (string.IsNullOrEmpty(json)) return null;
332	            return JsonConvert.DeserializeObject<ScoreResult>(json);
333	        }
334	
335	        // Overload: explicit roomId + playerId (used when the lobby remembers them itself
336	        // instead of reading from the URL).
337	        public static async Task<ScoreResult> SubmitRoomScore(string roomId, string playerId, int score, int playTimeMs)
338	        {
339	            string url  = GameBullEndpoints.RoomScore(roomId);
340	            string body = JsonConvert.SerializeObject(new { playerId = playerId, score = score, playTimeMs = playTimeMs });
341	            string json = await GameBullClient.PostJson(url, body);
342	            if (string.IsNullOrEmpty(json)) return null;
343	            return JsonConvert.DeserializeObject<ScoreResult>(json);
344	        }
345	
346	        // POST an open-tournament score (mode OPEN_TOURNAMENT). Token in body.
347	        public static async Task<ScoreResult> SubmitTournamentScore(int score, int playTimeMs)
348	        {
349	            string url  = GameBullEndpoints.TournamentScore(GameBullBoot.OpenTournamentId);
350	            string body = JsonConvert.SerializeObject(new {
351	                sessionToken = GameBullBoot.SessionToken,
352	                value        = score,
353	                playTimeMs   = playTimeMs
354	            });
355	            string json = await GameBullClient.PostJson(url, body);
356	            if (string.IsNullOrEmpty(json)) return null;
357	            return JsonConvert.DeserializeObject<ScoreResult>(json);
358	        }
359	
360	        // HOST: create a 4-player tournament room. Returns roomId + joinUrl (share link) + seed + hostPlayerId.
361	        public static async Task<CreateRoomResult> CreateRoom(string roomName, int expiresInSeconds, string hostNickname)
362	        {
363	            string url  = GameBullEndpoints.CreateRoom();
364	            string body = JsonConvert.SerializeObject(new {
365	                gameId           = GameBullBoot.GameId,
366	                roomName         = roomName,
367	                expiresInSeconds = expiresInSeconds,
368	                hostNickname     = hostNickname
369	            });
370	            string json = await GameBullClient.PostJson(url, body, GameBullBoot.SessionToken);
371	            if (string.IsNullOrEmpty(json)) return null;
372	            return JsonConvert.DeserializeObject<CreateRoomResult>(json);
373	        }
374	
375	        // JOINER: join a room by id (the friend's game has roomId from the URL). Returns this player's playerId + seed.
376	        public static async Task<JoinRoomResult> JoinRoom(string roomId, string nickname)
377	        {
378	            string url  = GameBullEndpoints.JoinRoom(roomId);
379	            string body = JsonConvert.SerializeObject(new {
380	                nickname = nickname
381	            });
382	            string json = await GameBullClient.PostJson(url, body, GameBullBoot.SessionToken);
383	            if (string.IsNullOrEmpty(json)) return null;
384	            return JsonConvert.DeserializeObject<JoinRoomResult>(json);
385	        }
386	
387	        // ---------- Open Tournament API ----------
388	
389	        public static async Task<OpenTournamentList> ListTournaments()
