447	        // stores the returned token as CurrentGlobalToken (used by score/leaderboard/my-rank) + the seed.
448	        // Returns null on failure (incl. play.no_lives) — caller must NOT start the game.
449	        public static async Task<TournamentSession> StartGlobalTournamentSession(string id)
450	        {
451	            Debug.Log("[LIVES] mint session — about to spend a life");
