function buildStops(){
  var vh=window.innerHeight, out=[];
  sections.forEach(function(s){
    var top=s.offsetTop, h=s.offsetHeight, bottom=top+h-vh;
    out.push({y:Math.round(top), sec:s, top:true});          // land on the section's top
    if(h>vh+8){                                              // taller than screen → add inner stops
      var n=Math.ceil((h-vh)/(vh*0.86));
      for(var i=1;i<=n;i++) out.push({y:Math.round(Math.min(bottom, top+i*(vh*0.86))), sec:s, top:false});
    }
  });
  out.sort(function(a,b){return a.y-b.y;});
  stops=out.filter(function(o,i){return i===0 || Math.abs(o.y-out[i-1].y)>4;});
}

input.new_string:
function buildStops(){
  var vh=window.innerHeight, out=[];
  sections.forEach(function(s){
    var top=Math.round(s.offsetTop), h=s.offsetHeight, bottom=Math.round(top+h-vh);
    out.push({y:top, sec:s, top:true});                     // section start (always a stop)
    // Only paginate a section that overflows the screen by a MEANINGFUL amount (>40% of a
    // screen). Otherwise it's one stop and ↓ flies straight to the next slide (no tiny nudge).
    if(bottom-top > vh*0.4){
      var y=top+vh*0.82;
      while(true){
        var sy=Math.min(bottom, Math.round(y));
        out.push({y:sy, sec:s, top:false});
        if(sy>=bottom) break;
        y+=vh*0.82;
      }
    }
  });
  out.sort(function(a,b){return a.y-b.y;});
  stops=out;
}

